-- Saída web 2025: preserva congelamento 63 e comparativos; altera somente 50 médias revisadas e 11 atividades.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=63 AND frozen AND status='ok' AND NOT truncated),
m AS (SELECT 'outros_esportes' AS serie,r->>'categoria' AS categoria,jsonb_build_object('valor',(r->>'percentual')::numeric,'contagem',(r->>'total')::bigint,'denominador',(r->>'denominador')::bigint)||jsonb_build_object('fonte','Notebook · execução #71 · fontes #69/#29 · 30/09/2026','nota',(r->>'tipo')||'; '||(r->>'excluidos_delete')||' registros excluídos neste tipo; denominador inclui Run e todos os tipos') AS atual FROM estudo.notebook_runs n CROSS JOIN LATERAL jsonb_array_elements(n.result->'rows') r WHERE n.id=71 AND n.frozen AND n.status='ok' AND NOT n.truncated AND (r->>'ano')::integer=2025 UNION ALL SELECT 'maratonas_'||(r->>'grupo'),r->>'categoria',jsonb_build_object('valor',r->>'revisado','contagem',(r->>'incluidos')::bigint,'denominador',(r->>'denominador')::bigint,'fonte','Notebook · execução #70 · fonte #67 · 30/09/2026','nota','Média de '||(r->>'incluidos')||' resultados; limite selecionado '||(r->>'tempo_limite')||'; '||(r->>'empatados_no_limite')||' resultados empatados no tempo limite; desempate por ID. Regra revisada, diferente da classificação legada.') FROM estudo.notebook_runs n CROSS JOIN LATERAL jsonb_array_elements(n.result->'rows') r WHERE n.id=70 AND n.frozen AND n.status='ok' AND NOT n.truncated),
notas AS(SELECT 'outros_esportes' AS serie,'Atividades importadas por activity_date de 01/01 a 31/12/2025, tipo preenchido; exclui indicação aspect_type=delete do Strava. Base: 1.139.568 atividades de todos os tipos, inclusive Run; 17.588 exclusões entre 1.157.156 registros com tipo e 3 sem tipo fora da base. Não conta usuários nem conclusões de provas. Os 11 tipos apresentados não somam 100%. Mapeamento exato registrado na consulta 284 rev1; Trilha=Hike. Fontes 282 rev2/69 e legado 223 rev1/29; comparação congelada 71, coleta 30/09/2026. Diferenças com o PDF incluem base atual e regra revisada, sem ajuste para coincidir.' AS nota UNION ALL SELECT serie,'Recálculo 2025: média dos menores tempos, ordenação global por tempo_total e id_resultado. Top 10/100 seleciona exatamente min(n,10/100); grupos percentuais usam ceil(n*p) de concluintes elegíveis. Média arredondada ao segundo. Mesma população de 43.395 conclusões do congelamento 41: BR, rua, 42–42,2 km, data final em 2025, status 0, homologado, concluinte, tempo positivo, PCD=false e exclusões de modalidade do SQL legado. Empates têm tamanho determinístico; quantidade e empate no limite documentados. Regra revisada difere do SQL 264/48 que usava classificação cadastrada e inscritos; não é reprodução da base histórica. Consulta 281 rev2/67; comparação PDF/legado/revisão 283 rev1/70; coleta 30/09/2026.' FROM m WHERE serie LIKE 'maratonas_top%' GROUP BY serie),
comps AS(SELECT c.value||CASE WHEN m.serie IS NOT NULL THEN jsonb_build_object('atual',m.atual,'status','notebook_em_conciliacao') ELSE '{}'::jsonb END AS item,c.ordinality AS ordem FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'comparacoes') WITH ORDINALITY c LEFT JOIN m ON m.serie=c.value->>'serie' AND m.categoria=c.value->>'categoria')
SELECT payload||jsonb_build_object('meta',payload->'meta'||jsonb_build_object('notebook_fontes',(payload->'meta'->'notebook_fontes')||(SELECT jsonb_agg(jsonb_build_object('execucao',id,'celula',cell_id,'revisao',cell_version,'coletado_em',started_at) ORDER BY id) FROM estudo.notebook_runs WHERE id IN(67,69,70,71) AND frozen)),'comparacoes',(SELECT jsonb_agg(item ORDER BY ordem) FROM comps),'conciliacao',jsonb_build_object('compativel_no_valor',0,'divergente',0,'nao_recalculado',0,'compativel_no_arredondamento',0,'notebook_em_conciliacao',0)||(SELECT jsonb_object_agg(status,total) FROM(SELECT item->>'status' AS status,count(*) AS total FROM comps GROUP BY 1) q),
'series',(SELECT jsonb_agg(s.value||CASE WHEN n.nota IS NOT NULL THEN jsonb_build_object('ressalva',n.nota) ELSE '{}'::jsonb END ORDER BY s.ordinality) FROM jsonb_array_elements(payload->'series') WITH ORDINALITY s LEFT JOIN notas n ON n.serie=s.value->>'id')) AS payload
FROM anterior WHERE(SELECT count(*) FROM m)=61 AND(SELECT count(*) FROM comps WHERE item->>'status'='notebook_em_conciliacao' AND item->>'serie' IN(SELECT serie FROM m))=61
